#!/bin/busybox ash
# bmarkus - 26/02/2014

if [ -f /etc/sysconfig/ntpserver ]; then
	echo "# Generated by pCP" > /etc/ntp.conf
	for IP in $(cat /etc/sysconfig/ntpserver); do
		echo "server $IP" >> /etc/ntp.conf
	done
	echo "# End pCP" > /etc/ntp.conf
fi

if ! grep -q "^server" /etc/ntp.conf; then
	cat > /etc/ntp.conf << EOF
# Generated by pCP
server 0.pool.ntp.org
server 1.pool.ntp.org
server time.cloudflare.com
server time.google.com
# End pCP
EOF
fi

/usr/sbin/ntpd -q
